import {
  generateId,
  roomAvailableSeats,
  type AllocationResult,
  type DutyAssignment,
  type DutyRoster,
  type Exam,
  type Room,
  type Teacher,
} from '../../core/index.js';
import { SeededRandom } from '../rng.js';
import { timingsOverlap } from '../scheduling/conflicts.js';
import { validateDutyRoster } from './dutyValidator.js';

/**
 * Teachers already on duty in another exam whose date+time overlaps this
 * one are unavailable - a real conflict check (can't be in two rooms at
 * once), not cosmetic and not configurable off. Only looks at each other
 * exam's *active* duty roster (its current, not-superseded version).
 */
export function findConflictingTeacherIds(exam: Exam, allExams: Exam[], allRosters: DutyRoster[]): Set<string> {
  const conflicting = new Set<string>();
  for (const other of allExams) {
    if (other.id === exam.id) continue;
    if (!timingsOverlap(exam, other)) continue;
    const activeRoster = allRosters.find((r) => r.id === other.activeDutyRosterId);
    if (!activeRoster) continue;
    for (const a of activeRoster.assignments) conflicting.add(a.teacherId);
  }
  return conflicting;
}

/**
 * Workload caps (spec: "max duty in one or two day", "shift-wise division")
 * are a *soft, configurable* fairness constraint distinct from the hard
 * time-overlap conflict above: a teacher can be free at the exact time of
 * two same-day exams yet still be excluded from a second one once they've
 * hit `maxDutiesPerDay`. Counts every *other* exam's active roster;
 * `maxDutiesPerDay`/`maxDutiesTotal` of 0 or undefined means "no limit".
 * This is enforced greedily in whatever order exams are generated, not via
 * a joint whole-datesheet solve - simple, deterministic, and matches how
 * the rest of the engine is built.
 */
export function findWorkloadExcludedTeacherIds(
  exam: Exam,
  allExams: Exam[],
  allRosters: DutyRoster[],
  maxDutiesPerDay?: number,
  maxDutiesTotal?: number
): Set<string> {
  const excluded = new Set<string>();
  if (!maxDutiesPerDay && !maxDutiesTotal) return excluded;

  const dayCounts = new Map<string, number>();
  const totalCounts = new Map<string, number>();

  for (const other of allExams) {
    if (other.id === exam.id) continue;
    const roster = allRosters.find((r) => r.id === other.activeDutyRosterId);
    if (!roster) continue;
    const sameDay = other.date === exam.date;
    for (const a of roster.assignments) {
      totalCounts.set(a.teacherId, (totalCounts.get(a.teacherId) ?? 0) + 1);
      if (sameDay) dayCounts.set(a.teacherId, (dayCounts.get(a.teacherId) ?? 0) + 1);
    }
  }

  const teacherIds = new Set([...dayCounts.keys(), ...totalCounts.keys()]);
  for (const id of teacherIds) {
    if (maxDutiesPerDay && (dayCounts.get(id) ?? 0) >= maxDutiesPerDay) excluded.add(id);
    if (maxDutiesTotal && (totalCounts.get(id) ?? 0) >= maxDutiesTotal) excluded.add(id);
  }
  return excluded;
}

export function buildBranchesInRoom(seatAllocation: AllocationResult | undefined): Map<string, Set<string>> {
  const map = new Map<string, Set<string>>();
  if (!seatAllocation) return map;
  const studentsById = new Map(seatAllocation.studentSnapshot.map((s) => [s.id, s]));
  for (const a of seatAllocation.assignments) {
    const student = studentsById.get(a.studentId);
    if (!student) continue;
    const set = map.get(a.roomId) ?? new Set<string>();
    set.add(student.branch);
    map.set(a.roomId, set);
  }
  return map;
}

/** Required invigilators for a room = ceil(available seats / seatsPerInvigilator), minimum 1 per enabled room. */
export function computeRoomDutyTargets(rooms: Room[], seatsPerInvigilator: number): Record<string, number> {
  const targets: Record<string, number> = {};
  const perInvigilator = Math.max(1, seatsPerInvigilator);
  for (const room of rooms) {
    const seats = roomAvailableSeats(room).length;
    targets[room.id] = Math.max(1, Math.ceil(seats / perInvigilator));
  }
  return targets;
}

/** Students seated per room in a finished seat allocation (roomId -> count). Rooms with nobody seated are absent. */
export function occupancyFromAllocation(seatAllocation: AllocationResult | undefined): Record<string, number> {
  const counts: Record<string, number> = {};
  if (!seatAllocation) return counts;
  for (const a of seatAllocation.assignments) counts[a.roomId] = (counts[a.roomId] ?? 0) + 1;
  return counts;
}

/**
 * Invigilators for occupied rooms only: ceil(students seated / studentsPerInvigilator),
 * minimum 1, optionally overridden per room. Rooms with no students get no entry at all.
 */
export function computeOccupiedRoomTargets(
  rooms: Room[],
  occupancy: Record<string, number>,
  studentsPerInvigilator: number,
  overrides: Record<string, number> = {}
): Record<string, number> {
  const targets: Record<string, number> = {};
  const per = Math.max(1, studentsPerInvigilator);
  for (const room of rooms) {
    const students = occupancy[room.id] ?? 0;
    if (students <= 0) continue;
    const override = overrides[room.id];
    targets[room.id] = override !== undefined && override >= 1 ? Math.floor(override) : Math.max(1, Math.ceil(students / per));
  }
  return targets;
}

export interface AllocateDutiesParams {
  examId: string;
  teachers: Teacher[];
  rooms: Room[];
  seatsPerInvigilator: number;
  avoidOwnBranchInvigilation: boolean;
  maxDutiesPerDay?: number;
  maxDutiesTotal?: number;
  seatAllocation?: AllocationResult;
  excludeTeacherIds?: Set<string>;
  seed?: number;
  version?: number;
  /**
   * Students seated per room. When given, only rooms with students get duty and
   * the count follows students (not seat capacity); `seatsPerInvigilator` then
   * means students per invigilator.
   */
  occupancy?: Record<string, number>;
  /** Per-room override of the invigilator count (occupancy mode). */
  roomTargetOverrides?: Record<string, number>;
  /** Use this teacher order as-is (e.g. least-loaded first) instead of a seeded shuffle. */
  orderedTeachers?: Teacher[];
  windowId?: string;
}

/**
 * Round-robin assignment of a shuffled (seeded) teacher list across rooms,
 * filling each room up to its own capacity-derived target one slot per pass
 * (a big room needing 2 invigilators doesn't get its 2nd until every room
 * needing at least 2 has gotten its 2nd too) - "equal distribution" now
 * means proportional to room size, not a flat count. Never forces an
 * own-branch violation or a double-booking to fill a slot - an unfillable
 * slot is reported honestly via `understaffedRoomIds` / `unassignedTeacherIds`.
 */
export function allocateDuties(params: AllocateDutiesParams): DutyRoster {
  const seed = params.seed ?? Math.floor(Math.random() * 2 ** 31);
  const rng = new SeededRandom(seed);
  const exclude = params.excludeTeacherIds ?? new Set<string>();

  const eligibleTeachers = params.teachers.filter((t) => t.active && !exclude.has(t.id));
  let rooms = params.rooms.filter((r) => r.enabled);
  if (params.occupancy) rooms = rooms.filter((r) => (params.occupancy![r.id] ?? 0) > 0);
  const branchesInRoom = params.avoidOwnBranchInvigilation ? buildBranchesInRoom(params.seatAllocation) : new Map<string, Set<string>>();
  const roomDutyTargets = params.occupancy
    ? computeOccupiedRoomTargets(rooms, params.occupancy, params.seatsPerInvigilator, params.roomTargetOverrides)
    : computeRoomDutyTargets(rooms, params.seatsPerInvigilator);

  const queue = params.orderedTeachers
    ? params.orderedTeachers.filter((t) => t.active && !exclude.has(t.id))
    : rng.shuffle(eligibleTeachers);
  const assignments: DutyAssignment[] = [];
  const roomCounts = new Map<string, number>(rooms.map((r) => [r.id, 0]));

  const maxPasses = rooms.length === 0 ? 0 : Math.max(...rooms.map((r) => roomDutyTargets[r.id] ?? 1));
  for (let pass = 0; pass < maxPasses; pass++) {
    for (const room of rooms) {
      if ((roomCounts.get(room.id) ?? 0) >= (roomDutyTargets[room.id] ?? 1)) continue;
      let pickIndex = -1;
      for (let i = 0; i < queue.length; i++) {
        const candidate = queue[i]!;
        if (params.avoidOwnBranchInvigilation && branchesInRoom.get(room.id)?.has(candidate.branch)) continue;
        pickIndex = i;
        break;
      }
      if (pickIndex === -1) continue;
      const teacher = queue.splice(pickIndex, 1)[0]!;
      assignments.push({ teacherId: teacher.id, roomId: room.id });
      roomCounts.set(room.id, (roomCounts.get(room.id) ?? 0) + 1);
    }
  }

  const unassignedTeacherIds = queue.map((t) => t.id);
  const understaffedRoomIds = rooms.filter((r) => (roomCounts.get(r.id) ?? 0) < (roomDutyTargets[r.id] ?? 1)).map((r) => r.id);

  const base = {
    assignments,
    roomDutyTargets,
    avoidOwnBranchInvigilation: params.avoidOwnBranchInvigilation,
  };
  const validationReport = validateDutyRoster(base, params.teachers, rooms, branchesInRoom);

  return {
    id: generateId('duty'),
    examId: params.examId,
    generatedAt: new Date().toISOString(),
    seed,
    seatsPerInvigilator: params.seatsPerInvigilator,
    roomDutyTargets,
    maxDutiesPerDay: params.maxDutiesPerDay,
    maxDutiesTotal: params.maxDutiesTotal,
    avoidOwnBranchInvigilation: params.avoidOwnBranchInvigilation,
    assignments,
    manualOverrides: [],
    unassignedTeacherIds,
    understaffedRoomIds,
    validationReport,
    version: params.version ?? 1,
    windowId: params.windowId,
    basedOnAllocationId: params.seatAllocation?.id,
    basis: params.occupancy ? 'students' : 'seats',
  };
}
